void VIOManager::slideFeatMap()
{
  // Mirrors VoxelMapManager::mapSliding()/clearMemOutOfMap() in voxel_map.cpp,
  // but for VIOManager's own feat_map (there is no shared state between the
  // two maps or their sliding windows). Left unbounded, feat_map only grows
  // as new visual features are discovered, which is what caused multi-GB/hr
  // RSS growth on long real-robot runs.
  if (!feat_map_sliding_en || new_frame_ == nullptr) return;

  V3D current_pos = new_frame_->pos();
  if (feat_map_slide_initialized_ && (current_pos - feat_map_last_slide_position_).norm() < feat_map_sliding_thresh)
  {
    return;
  }
  feat_map_last_slide_position_ = current_pos;
  feat_map_slide_initialized_ = true;

  const double voxel_size = 0.5;  // must match insertPointIntoVoxelMap()'s voxel_size
  float loc_xyz[3];
  for (int j = 0; j < 3; j++)
  {
    loc_xyz[j] = current_pos[j] / voxel_size;
    if (loc_xyz[j] < 0) { loc_xyz[j] -= 1.0; }
  }
  const int64_t cx = (int64_t)loc_xyz[0];
  const int64_t cy = (int64_t)loc_xyz[1];
  const int64_t cz = (int64_t)loc_xyz[2];
  const int64_t half = (int64_t)feat_map_half_size;

  int deleted = 0;
  for (auto it = feat_map.begin(); it != feat_map.end(); )
  {
    const VOXEL_LOCATION &loc = it->first;
    bool should_remove = loc.x > cx + half || loc.x < cx - half ||
                          loc.y > cy + half || loc.y < cy - half ||
                          loc.z > cz + half || loc.z < cz - half;
    if (should_remove)
    {
      delete it->second;  // ~VOXEL_POINTS() also deletes each contained VisualPoint*
      it = feat_map.erase(it);
      deleted++;
    }
    else
    {
      ++it;
    }
  }
  std::cout << "[ VIO ] feat_map slide: removed " << deleted << " voxels, " << feat_map.size() << " remain\n";
}

