cv::Mat img_cur = getImageFromMsg(msg);
img_buffer.push_back(img_cur);
img_time_buffer.push_back(img_time_correct);

// img_buffer had no size cap at all: if the main sync/process loop falls
// behind the ~15Hz camera rate for any reason (a slow cycle, a stall
// waiting on lidar/imu sync), converted images (~MBs each, from
// getImageFromMsg's cv::cvtColor) piled up here indefinitely. Measured
// via heaptrack: 1.9GB/1.92GB peak consumption traced to exactly this
// img_cbk -> getImageFromMsg -> cv_bridge::toCvCopy -> cv::cvtColor path,
// growing tens of MB/s with no corresponding LIO/VIO processing progress.
// Keep only the most recent frames; older ones are stale for real-time
// SLAM regardless.
const size_t kMaxImgBufferSize = 5;
while (img_buffer.size() > kMaxImgBufferSize)
{
  img_buffer.pop_front();
  img_time_buffer.pop_front();
}

// ROS_INFO("Correct Image time: %.6f", img_time_correct);

