void LIVMapper::RGBpointBodyToWorld(PointType const *const pi, PointType *const po)
{
  V3D p_body(pi->x, pi->y, pi->z);
  V3D p_global(_state.rot_end * (extR * p_body + extT) + _state.pos_end);
  po->x = p_global(0);
  po->y = p_global(1);
  po->z = p_global(2);
  po->intensity = pi->intensity;
}

void LIVMapper::standard_pcl_cbk(const sensor_msgs::PointCloud2::ConstSharedPtr &msg)
{
  if (!lidar_en) return;
  mtx_buffer.lock();
  // cout<<"got feature"<<endl;
  if (stamp_to_sec(msg->header.stamp) < last_timestamp_lidar)
  {
    ROS_ERROR("lidar loop back, clear buffer");
    lid_raw_data_buffer.clear();
  }
  // ROS_INFO("get point cloud at time: %.6f", msg->header.stamp.toSec());
  PointCloudXYZI::Ptr ptr(new PointCloudXYZI());
  p_pre->process(msg, ptr);
  lid_raw_data_buffer.push_back(ptr);
  lid_header_time_buffer.push_back(stamp_to_sec(msg->header.stamp));
  // NOTE: deliberately not capped here, unlike img_buffer. heaptrack never
  // showed this buffer as an actual contributor, and unlike img_buffer,
  // sync_packages() has a code path that pops from *this* deque's front
  // without holding mtx_buffer -- trimming from the producer side raced
  // with that and crashed fastlivo_mapping with SIGSEGV. Revisit only with
  // a confirmed leak here and a plan for that lock gap, not defensively.
  last_timestamp_lidar = stamp_to_sec(msg->header.stamp);

  mtx_buffer.unlock();
  sig_buffer.notify_all();
}

