void VIOManager::processFrame(cv::Mat &img, vector<pointWithVar> &pg, const unordered_map<VOXEL_LOCATION, VoxelOctoTree *> &feat_map, double img_time)
{
  if (img.empty())
  {
    printf("[ VIO ] Empty Image!\n");
    return;
  }

  if (width != img.cols || height != img.rows)
  {
    static int mismatch_warn_count = 0;
    if (mismatch_warn_count < 20)
    {
      const double input_ratio = static_cast<double>(img.cols) / static_cast<double>(img.rows);
      const double model_ratio = static_cast<double>(width) / static_cast<double>(height);
      printf("[ VIO ] Resizing image to camera model size: input=%dx%d, model=%dx%d (ratio %.3f -> %.3f)\n",
             img.cols, img.rows, width, height, input_ratio, model_ratio);
      mismatch_warn_count++;
    }
    cv::resize(img, img, cv::Size(width, height), 0, 0, cv::INTER_LINEAR);
  }
  img_rgb = img.clone();
  img_cp = img.clone();
  // img_test = img.clone();

  if (img.channels() == 3) cv::cvtColor(img, img, CV_BGR2GRAY);

  try
  {
    new_frame_.reset(new Frame(cam, img));
  }
  catch (const std::exception &e)
  {
    printf("[ VIO ] Frame init failed: %s\n", e.what());
    return;
  }
  updateFrameState(*state);

  resetGrid();

