// Livox SDK reports acc_x/y/z in units of g (confirmed empirically: a
// stationary unit read ~1.0 magnitude here, vs. the ~9.8 m/s^2 a level
// accelerometer should report at rest). sensor_msgs/Imu.linear_acceleration
// is specified in m/s^2 (REP-145/103); this was being published unscaled,
// so every downstream consumer (FAST-LIVO's EKF gravity/bias init included)
// saw acceleration ~9.8x too small. That left most of the true gravity
// vector unaccounted for and misread as real linear acceleration, which
// integrates into large phantom velocity/position drift even at rest
// (observed: ~0.4 m/s of apparent drift on a physically stationary robot).
constexpr double kStandardGravityMPerS2 = 9.80665;
imu_msg.linear_acceleration.x = imu_data.acc_x * kStandardGravityMPerS2;
imu_msg.linear_acceleration.y = imu_data.acc_y * kStandardGravityMPerS2;
imu_msg.linear_acceleration.z = imu_data.acc_z * kStandardGravityMPerS2;

